#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, MOD;
    cin >> N >> MOD;
    vector<long long> DP(N, 0);
    DP[0] = 1;
    vector<long long> Cum(N + 1, 0);
    Cum[1] = 1;
    for (int idx = 1; idx < N; ++idx) {
        int i2 = N - idx;
        long long current_sum = Cum[idx];
        int j = 2;
        while (true) {
            if (i2 * j > N) break;
            long long start_idx = N - i2 * j + 1;
            long long end_idx = max(0LL, N - i2 * j - j + 1);
            current_sum += Cum[start_idx] - Cum[end_idx];
            current_sum %= MOD;
            ++j;
        }
        Cum[idx + 1] = (Cum[idx] + current_sum) % MOD;
        DP[idx] = current_sum;
    }
    cout << DP[N - 1] << "\n";
    return 0;
}
